package com.example.rokidgeminisecretary;
import org.json.*;import java.util.*;
public final class RepairCases {
 static int n;static void ok(boolean b,String s){n++;if(!b)throw new AssertionError(s);}
 static JSONObject ride(String line,String type,double a,double b)throws Exception {JSONObject s=MultimodalJourneyTest.ride("from "+line,"to "+line,35+a,139,35+b,139);return s.put("staticDuration","100s").put("distanceMeters",1000).put("polyline",new JSONObject().put("encodedPolyline",GooglePolyline.encode(Arrays.asList(new double[]{35+a,139},new double[]{35+b,139})))).put("transitDetails",s.getJSONObject("transitDetails").put("transitLine",new JSONObject().put("name",line).put("vehicle",new JSONObject().put("type",type))));}
 public static void main(String[] args)throws Exception {
  JSONObject train=ride("train","SUBWAY",0,.01),bus=ride("bus","BUS",.02,.03),walk=new JSONObject().put("travelMode","WALK").put("staticDuration","60s").put("distanceMeters",100).put("polyline",new JSONObject().put("encodedPolyline",GooglePolyline.encode(Arrays.asList(new double[]{35.01,139},new double[]{35.02,139}))));
  JSONObject route=MultimodalJourneyTest.route(train,walk,bus);GooglePolyline.mergeSteps(route);
  MultimodalJourney p=new MultimodalJourney("public fixture",new double[]{35.04,139},"bicycling","bicycling");p.stations(route);p.ready=true;
  ok(p.boardingChoices().length()==2,"all selected train/bus offered");ok(!p.board(-1),"multiple rides require selection");ok(!p.board(1),"walking cannot be boarded");ok(p.board(2),"bus selected while already aboard");ok(p.manualTransitIndex==2,"selected bus index retained");
  JSONObject segment=p.fetchPhase(Double.NaN,Double.NaN,(a,b,c,e,m)->{throw new AssertionError("provider requery on boarding");});ok(segment.getJSONArray("legs").getJSONObject(0).getJSONArray("steps").getJSONObject(2).getJSONObject("transitDetails").getJSONObject("transitLine").getString("name").equals("bus"),"bus not replaced by subway");
  JourneyProgress progress=new JourneyProgress(TransitJourney.parse("fixture",segment,100));progress.confirmRide(2);JSONObject state=progress.snapshot(Double.NaN,Double.NaN,-1,0,100,new JSONArray());ok(state.getBoolean("rideConfirmed"),"manual ride without GPS");ok(!state.getBoolean("positionConfirmed"),"manual boarding never fabricates GPS");ok(state.getJSONObject("currentLeg").getString("lineName").equals("bus"),"manual bus presentation");
  p=new MultimodalJourney("fixture",new double[]{35.04,139},"walking","walking");p.stations(route);p.ready=true;ok(p.board(0),"first train confirmation");p.ready=true;ok(p.advance("alight")&&p.phase==MultimodalJourney.Phase.BOARDING,"intermediate alight retains transfer");p.ready=true;ok(p.boardingChoices().length()==1&&p.boardingChoices().getJSONObject(0).getInt("index")==2,"next ride after transfer");
  MultimodalJourney moving=new MultimodalJourney("fixture",new double[]{35.04,139},"walking","walking");moving.stations(route);moving.ready=true;
  ok(moving.inferRide(35.025,139,10,6,100000,100000)==-1,"one moving fix insufficient");ok(moving.inferRide(35.025,139,10,6,100000,101000)==-1,"poll repeat cannot prove movement");ok(moving.inferRide(35.025,139,10,6,106000,106000)==2,"new moving fixes match selected bus");ok(moving.inferRide(35.025,139,10,1,112000,112000)==-1,"walking speed cannot board");ok(moving.inferRide(35.025,139,100,6,112000,112000)==-1,"poor accuracy cannot board");
  JSONObject manualHud=com.example.rokidkeyboardbridge.GlassRepairCases.manualHud(state);ok(manualHud.getString("instruction").contains("バス"),"manual bus remains visible without GPS");
  ok(StepCountContinuity.estimate(8000,12000,12020,11900,true)==8020,"retain full-day baseline plus delta");ok(StepCountContinuity.estimate(8000,12000,20,0,true)==8000,"reboot cannot erase full-day baseline");ok(StepCountContinuity.estimate(8000,-1,20,0,true)==8000,"unknown sensor anchor avoids double count");ok(StepCountContinuity.estimate(8000,12000,20,5,false)==15,"new day does not reuse yesterday");
  MultimodalJourneyTest.main(new String[0]);com.example.rokidkeyboardbridge.GlassRepairCases.main(new String[0]);System.out.println("RepairCases PASS "+n);
 }
}
